#include <algorithm>
#include <string>
#include <vector>

std::vector<std::string> sort_words(std::vector<std::string> words) {
    std::sort(words.begin(), words.end(),
              [](const std::string& a, const std::string& b) {
                  if (a.size() != b.size()) return a.size() < b.size();
                  return a < b;
              });
    return words;
}

